          startVertexIndex + i + 2
        ];
        localFaces.push(face);
        this.faces.push(face);
      }
    }

    this.objects.push({
      name: objectName,
      vertexStart: startVertexIndex,
      vertexCount: localVertices.length,
      faceStart: this.faces.length - localFaces.length,
      faceCount: localFaces.length
    });

    console.log(`Processed ${objectName}: ${localVertices.length} vertices, ${localFaces.length} faces`);
  }

  /**
   * Process InstancedMesh (for axis pins)
   */
  processInstancedMesh(instancedMesh, objectName) {
    const geometry = instancedMesh.geometry;
    const count = instancedMesh.count;

    if (!geometry) {
      console.warn(`InstancedMesh ${objectName} has no geometry`);
      return;
    }

    const baseGeom = geometry.clone();
    const matrix = new THREE.Matrix4();
    const tempMesh = new THREE.Mesh(baseGeom);

    // Update world matrix for the instanced mesh
    instancedMesh.updateMatrixWorld(true);

    for (let i = 0; i < count; i++) {
      // Get instance matrix
      instancedMesh.getMatrixAt(i, matrix);

      // Create a temporary mesh for this instance
      const instanceGeom = baseGeom.clone();

      // Apply instance transformation
      instanceGeom.applyMatrix4(matrix);

      // Apply world transformation
      instanceGeom.applyMatrix4(instancedMesh.matrixWorld);

      // Process as regular geometry
      const positions = instanceGeom.attributes.position;
      const startVertexIndex = this.vertexIndex;
      const localVertices = [];

      // Extract vertices and apply Blender rotation
      for (let j = 0; j < positions.count; j++) {
        const vertex = new THREE.Vector3(
          positions.getX(j),
          positions.getY(j),
          positions.getZ(j)
        );

        const blenderVertex = this.applyBlenderRotation(vertex);

        this.vertices.push(blenderVertex);
        localVertices.push(this.vertexIndex++);
      }

      // Extract faces
      const localFaces = [];

      if (instanceGeom.index) {
        const indices = instanceGeom.index.array;
        for (let j = 0; j < indices.length; j += 3) {
          const face = [
            startVertexIndex + indices[j],
            startVertexIndex + indices[j + 1],
            startVertexIndex + indices[j + 2]
          ];
          localFaces.push(face);
          this.faces.push(face);
        }
      } else {
        for (let j = 0; j < positions.count; j += 3) {
          const face = [
            startVertexIndex + j,
            startVertexIndex + j + 1,
            startVertexIndex + j + 2
          ];
          localFaces.push(face);
          this.faces.push(face);
        }
      }

      this.objects.push({
        name: `${objectName}_instance_${i}`,
        vertexStart: startVertexIndex,
        vertexCount: localVertices.length,
        faceStart: this.faces.length - localFaces.length,
        faceCount: localFaces.length
      });

      console.log(`Processed ${objectName}_instance_${i}: ${localVertices.length} vertices, ${localFaces.length} faces`);
    }
  }

  /**
   * Recursively traverse scene and extract all meshes
   */
  traverseScene(object, parentName = '') {
    const objectName = object.name || 'unnamed';
    const fullName = parentName ? `${parentName}_${objectName}` : objectName;

    if (object instanceof THREE.InstancedMesh) {
      this.processInstancedMesh(object, fullName);
    } else if (object instanceof THREE.Mesh) {
      this.processMesh(object, fullName);
    }

    if (object.children) {
      for (const child of object.children) {
        this.traverseScene(child, fullName);
      }
    }
  }

  /**
   * Generate OBJ file content
   */
  generateOBJ() {
    let objContent = '# Converted from Three.js to Blender Z-up coordinate system\n';
    objContent += '# Applied -90 degree X-rotation\n\n';

    // Write vertices
    for (const vertex of this.vertices) {
      objContent += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
    }

    objContent += '\n';

    // Write objects and faces
    let currentFaceIndex = 0;
    for (const obj of this.objects) {
      objContent += `o ${obj.name}\n`;

      // Write faces for this object
      for (let i = 0; i < obj.faceCount; i++) {
        const face = this.faces[obj.faceStart + i];
        objContent += `f ${face[0]} ${face[1]} ${face[2]}\n`;
      }

      objContent += '\n';
    }

    return objContent;
  }

  /**
   * Export scene to OBJ file
   */
  exportScene(scene, outputPath) {
    console.log('Starting OBJ export...');

    // Traverse and process all meshes
    this.traverseScene(scene);

    // Generate OBJ content
    const objContent = this.generateOBJ();

    // Ensure output directory exists
    const outputDir = path.dirname(outputPath);
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    // Write to file
    fs.writeFileSync(outputPath, objContent, 'utf8');

    console.log(`\nExport complete!`);
    console.log(`Total vertices: ${this.vertices.length}`);
    console.log(`Total faces: ${this.faces.length}`);
    console.log(`Total objects: ${this.objects.length}`);
    console.log(`Output file: ${outputPath}`);
  }
}

